import unreal_engine as ue
import json
from unreal_engine.classes import ActorComponent
world = ue.get_editor_world()

def sval(v):
    try:
        if v is None:
            return None
        if isinstance(v, (str, int, float, bool)):
            return v
        if isinstance(v, (list, tuple)):
            return [sval(x) for x in v]
        return str(v)
    except Exception as e:
        return '<ERR %s>' % e

def loc_tuple(a):
    try:
        l = a.get_actor_location()
        return [float(l[0]), float(l[1]), float(l[2])] if isinstance(l, tuple) else sval(l)
    except Exception as e:
        return '<loc err %s>' % e

def label_of(a):
    try:
        return a.get_actor_label()
    except Exception:
        return a.get_name()

def read_matching_attrs(obj, keys):
    out = {}
    for name in dir(obj):
        low = name.lower()
        if any(k in low for k in keys):
            try:
                val = getattr(obj, name)
            except Exception as e:
                val = '<ERR %s>' % e
            if not callable(val):
                out[name] = sval(val)
    return out

keys = ['way', 'path', 'spawn', 'mob', 'nav', 'patrol', 'point', 'config', 'range', 'height', 'count']
actor_rows = []
for a in world.all_actors():
    label = label_of(a)
    cname = a.get_class().get_name()
    text = (label + ' ' + a.get_name() + ' ' + cname).lower()
    if any(k.lower() in text for k in ['spawn', 'spawner', 'mons', 'mob', 'waypoint', 'aiway', 'aiworld', 'nav', 'volume']):
        row = {'label': label, 'name': a.get_name(), 'class': cname, 'location': loc_tuple(a)}
        row['actor_attrs'] = read_matching_attrs(a, keys)
        comps = []
        try:
            for c in a.get_components_by_class(ActorComponent):
                cn = c.get_class().get_name()
                n = c.get_name()
                if any(k.lower() in (cn + ' ' + n).lower() for k in ['way', 'spawn', 'mob', 'nav', 'point', 'logic', 'behavior']):
                    comps.append({'name': n, 'class': cn, 'attrs': read_matching_attrs(c, keys)})
        except Exception as e:
            row['component_error'] = str(e)
        row['components'] = comps
        actor_rows.append(row)

# selected actors separately
selected = []
try:
    # editor utility may not expose selected list in this runtime; use context if available not needed
    pass
except Exception:
    pass

summary = {
    'count': len(actor_rows),
    'actors': actor_rows[:200]
}
ue.log(json.dumps(summary, ensure_ascii=False, indent=2))
__askq_result = summary
