$code=@'
import unreal_engine as ue
import json, math
world = ue.get_editor_world()

def label(a):
    try: return a.get_actor_label()
    except Exception: return a.get_name()

def loc(a):
    l = a.get_actor_location()
    return {'x': round(l.x,3), 'y': round(l.y,3), 'z': round(l.z,3)}

def val(obj, name):
    try:
        v = getattr(obj, name)
        return str(v) if not isinstance(v, (str,int,float,bool,type(None))) else v
    except Exception as e:
        return '<ERR %s>' % e

spawners=[]
waypoints={}
volumes=[]
for a in world.all_actors():
    cname=a.get_class().get_name()
    lab=label(a)
    if cname == 'AIWayPointActor':
        waypoints[lab]=loc(a)
    if cname == 'Mons_Spawner_C':
        wp_arr=[]
        wp_count=-1
        try:
            arr=a.STSpawnerWayPoint.WayPointArr
            wp_count=len(arr)
            for wp in arr:
                if wp:
                    wp_arr.append({'label': label(wp), 'loc': loc(wp)})
                else:
                    wp_arr.append({'label': None, 'loc': None})
        except Exception as e:
            wp_arr=['<ERR %s>' % e]
        spawners.append({
            'label': lab,
            'name': a.get_name(),
            'loc': loc(a),
            'UsePathPoint': val(a,'UsePathPoint'),
            'PathType': val(a, '路点寻路方式'),
            'bUseNavMesh': val(a,'bUseNavMesh'),
            'Range': val(a,'Range'),
            'Height': val(a,'Height'),
            'bTraceGround': val(a,'bTraceGround'),
            'MinSpawnCount': val(a,'MinSpawnCount'),
            'MaxSpawnCount': val(a,'MaxSpawnCount'),
            'MobCountPerSpawn': val(a,'MobCountPerSpawn'),
            'MobConfig': val(a,'MobConfig'),
            'WayPointCount': wp_count,
            'WayPoints': wp_arr,
        })
    if 'Volume' in cname or 'Nav' in cname:
        item={'label': lab, 'class': cname, 'loc': loc(a)}
        for meth in ['get_actor_bounds']:
            try:
                item[meth]=str(getattr(a,meth)())
            except Exception as e:
                item[meth]='<ERR %s>' % e
        try:
            item['RootRelativeScale3D']=str(a.RootComponent.RelativeScale3D)
            item['RootRelativeLocation']=str(a.RootComponent.RelativeLocation)
        except Exception as e:
            item['root_err']=str(e)
        volumes.append(item)

# Sort naturally by trailing number when possible
def sortkey(row):
    import re
    m=re.search(r'(\d+)$', row['label'])
    return int(m.group(1)) if m else -1
spawners=sorted(spawners, key=sortkey)
summary={'spawner_count':len(spawners),'waypoint_count':len(waypoints),'spawners':spawners,'volumes':volumes}
ue.log(json.dumps(summary, ensure_ascii=False, indent=2))
__askq_result=summary
